#include <bits/stdc++.h>
using namespace std;
const int MOD=1e9+7;
const int MAX=1<<20;
int n,mask_end,final_ans,p1_state[MAX],p2_state[MAX];
int grid_flags[10][10],grid_values[10][10],h_values[10][10][10];

int fastExponentiation(int base, int exponent) {
    int result=1;
    while (exponent > 0) {
        if (exponent & 1) result=1LL*result*base%MOD;
        base=1LL*base*base%MOD;
        exponent>>=1;
    }
    return result;
}

int getInverse(int x) { return fastExponentiation(x,MOD-2); }

bool validateTriplet(int x,int y,int z) {
    int arr[3]={x,y,z},perm[3]={0,1,2};
    do {
        if (grid_flags[arr[perm[0]]][1] && grid_flags[arr[perm[1]]][2] && grid_flags[arr[perm[2]]][3]) return true;
    } while (next_permutation(perm,perm+3));
    return false;
}

void dfsPartOne(int P,int x,int y) {
    if (x==7 && y==1) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (validateTriplet(i,j,k)) {
                        int X=1;
                        while (X==i || X==j || X==k) X++;
                        int Y=X+1;
                        while (Y==i || Y==j || Y==k) Y++;
                        int Z=Y+1;
                        while (Z==i || Z==j || Z==k) Z++;
                        state|=h_values[X][Y][Z];
                    }
        p1_state[state]=(p1_state[state]+P)%MOD;
        return;
    }
    grid_flags[x][y]=1;
    if (y==3) dfsPartOne(1LL*P*grid_values[x][y]%MOD,x+1,1);
    else dfsPartOne(1LL*P*grid_values[x][y]%MOD,x,y+1);
    grid_flags[x][y]=0;
    if (y==3) dfsPartOne(1LL*P*(MOD+1-grid_values[x][y])%MOD,x+1,1);
    else dfsPartOne(1LL*P*(MOD+1-grid_values[x][y])%MOD,x,y+1);
}

void dfsPartTwo(int P,int x,int y) {
    if (x==7 && y==4) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (validateTriplet(i,j,k)) state|=h_values[i][j][k];
        p2_state[state]=(p2_state[state]+P)%MOD;
        final_ans=(final_ans+1LL*p1_state[mask_end^state]*P%MOD)%MOD;
        return;
    }
    grid_flags[x][y-3]=1;
    if (y==6) dfsPartTwo(1LL*P*grid_values[x][y]%MOD,x+1,4);
    else dfsPartTwo(1LL*P*grid_values[x][y]%MOD,x,y+1);
    grid_flags[x][y-3]=0;
    if (y==6) dfsPartTwo(1LL*P*(MOD+1-grid_values[x][y])%MOD,x+1,4);
    else dfsPartTwo(1LL*P*(MOD+1-grid_values[x][y])%MOD,x,y+1);
}

int main() {
    scanf("%d",&n);
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            scanf("%d",&grid_values[i][j]),grid_values[i][j]=1LL*grid_values[i][j]*getInverse(100)%MOD;
    for (int i=n+1; i<=6; i++) grid_values[i][i]=1;
    int total=0;
    for (int i=1; i<=6; i++)
        for (int j=i+1; j<=6; j++)
            for (int k=j+1; k<=6; k++) 
                h_values[i][j][k]=1<<total++;
    dfsPartOne(1,1,1);
    mask_end=(1<<20)-1;
    for (int i=0; i<=19; i++)
        for (int j=0; j<=mask_end; j++) 
            if (j>>i&1) p1_state[j]=(p1_state[j]+p1_state[j^1<<i])%MOD;
    dfsPartTwo(1,1,4);
    final_ans=(MOD+1-final_ans)%MOD;
    printf("%d\n",final_ans);
    return 0;
}
